<?php

/**
 * Provision a disposable LocalWP site as a content-migration corpus target. Dev-only.
 *
 * The unit-economics baseline times a person migrating pages by hand and an operator migrating
 * the same kind of page with the tool. Both must land in the same target, and it must be the
 * target the paid wired measurement scores against. This writes that target into a site as a
 * mu-plugin, generated by `DBVC_CC_Corpus_Target_Translation` from the corpus's pinned
 * `target-schema.v1.json`: the same translation the wired test loads into its ACF doubles.
 *
 * It is not a product surface: no `wp dbvc` command, no REST route, no setting. It runs inside the
 * target site through WP-CLI's `eval-file`:
 *
 *   wp --path=<site>/app/public eval-file scripts/content-migration-target-site.php \
 *       <provision|verify|teardown> expect-site-url=<the site's siteurl> [options]
 *
 *   provision  Write the target mu-plugin. Needs ACF with repeater fields (ACF Pro, or Secure
 *              Custom Fields); refuses a site that has real content.
 *   verify     Project the live catalog through the shipped bridge and write it as JSON
 *              (out=<path>). Needs the DBVC plugin active. Compare with the wired
 *              measurement's doubles by running, from this repository:
 *                DBVC_CC_TARGET_SITE_PROJECTION=<path> vendor/bin/phpunit \
 *                  --filter ContentMigrationCorpusTargetProvisioningTest
 *   teardown   Remove the mu-plugin. Only ever removes a file this script generated.
 *
 * Options:
 *   slot=<dir>       Directory holding a target-schema.v1.json. Default: the pinned schema corpus
 *                    slot 1 uses (addons/content-migration/tests/corpus/target).
 *   out=<path>       verify only: where to write the projection.
 *   domain=<key>     verify only: the content-migration domain key the catalog is built under.
 *
 * Refusals. It will not touch a site whose WordPress root holds this repository, a site whose
 * host is listed as protected (this repository's own dev site, plus any host in the
 * comma-separated DBVC_CC_PROTECTED_SITES), or a site whose siteurl is not the one the operator
 * named with expect-site-url=<url>.
 */

if (! defined('ABSPATH') || ! defined('WP_CLI') || ! WP_CLI) {
    fwrite(STDERR, "Run this through WP-CLI: wp --path=<site> eval-file " . basename(__FILE__) . " <command>\n");
    exit(1);
}

require_once dirname(__DIR__) . '/addons/content-migration/tests/corpus/target/corpus-target-translation.php';
require_once dirname(__DIR__) . '/addons/content-migration/tests/corpus/target/corpus-target-projection.php';

/**
 * Hosts this script never provisions, whatever the operator passes.
 */
const DBVC_CC_TARGET_SITE_PROTECTED_HOSTS = ['dbvc-codexchanges.local'];

/**
 * A disposable site has WordPress's sample content at most. More than this many published
 * posts and pages means someone's site, not a fresh one.
 */
const DBVC_CC_TARGET_SITE_MAX_EXISTING_CONTENT = 3;

const DBVC_CC_TARGET_SITE_MU_PLUGIN = 'dbvc-cc-corpus-target.php';

/**
 * @param array<int, string> $args
 * @return array{0: string, 1: array<string, string>}
 */
function dbvc_cc_target_site_parse_args(array $args)
{
    $command = '';
    $options = [];
    foreach ($args as $arg) {
        // WP-CLI claims every `--option` for itself, so options reach this file as `key=value`.
        if (strpos($arg, '=') !== false) {
            $pair = explode('=', ltrim($arg, '-'), 2);
            $options[$pair[0]] = $pair[1];
        } elseif ($command === '') {
            $command = $arg;
        }
    }

    return [$command, $options];
}

/**
 * The WordPress root that holds this repository, so the script can refuse to provision it.
 *
 * @return string
 */
function dbvc_cc_target_site_own_root()
{
    $dir = __DIR__;
    while ($dir !== dirname($dir)) {
        if (is_file($dir . '/wp-config.php') || is_file($dir . '/wp-load.php')) {
            return wp_normalize_path((string) realpath($dir));
        }
        $dir = dirname($dir);
    }

    return '';
}

/**
 * @param array<string, string> $options
 * @return void
 */
function dbvc_cc_target_site_guard(array $options)
{
    $site_root = wp_normalize_path((string) realpath(ABSPATH));
    $own_root = dbvc_cc_target_site_own_root();
    if ($own_root !== '' && $site_root === $own_root) {
        WP_CLI::error('Refusing: this is the WordPress site that holds this repository.');
    }

    $site_url = untrailingslashit((string) get_option('siteurl'));
    $host = strtolower((string) wp_parse_url($site_url, PHP_URL_HOST));
    $protected = DBVC_CC_TARGET_SITE_PROTECTED_HOSTS;
    $extra = getenv('DBVC_CC_PROTECTED_SITES');
    if (is_string($extra) && $extra !== '') {
        $protected = array_merge($protected, array_map('trim', explode(',', strtolower($extra))));
    }
    if (in_array($host, $protected, true)) {
        WP_CLI::error(sprintf('Refusing: %s is a protected site.', $host));
    }

    $expected = untrailingslashit((string) ($options['expect-site-url'] ?? ''));
    if ($expected === '' || $expected !== $site_url) {
        WP_CLI::error(sprintf(
            'Refusing: name the site you mean with expect-site-url=<url>. This site is %s.',
            $site_url
        ));
    }
}

/**
 * @param array<string, string> $options
 * @return DBVC_CC_Corpus_Target_Translation
 */
function dbvc_cc_target_site_translation(array $options, &$schema_path = '')
{
    $slot = isset($options['slot']) && $options['slot'] !== ''
        ? rtrim($options['slot'], '/')
        : dirname(__DIR__) . '/addons/content-migration/tests/corpus/target';
    $schema_path = $slot . '/target-schema.v1.json';

    try {
        return DBVC_CC_Corpus_Target_Translation::from_file($schema_path);
    } catch (InvalidArgumentException $e) {
        WP_CLI::error($e->getMessage());
    }
}

/**
 * @return string
 */
function dbvc_cc_target_site_mu_plugin_path()
{
    return trailingslashit(WPMU_PLUGIN_DIR) . DBVC_CC_TARGET_SITE_MU_PLUGIN;
}

/**
 * @param string $path
 * @return bool
 */
function dbvc_cc_target_site_is_generated($path)
{
    $head = is_readable($path) ? (string) file_get_contents($path, false, null, 0, 2048) : '';

    return strpos($head, DBVC_CC_Corpus_Target_Translation::GENERATED_MARKER) !== false;
}

/**
 * @param array<string, string> $options
 * @return void
 */
function dbvc_cc_target_site_provision(array $options)
{
    if (! function_exists('acf_add_local_field_group') || ! function_exists('acf_get_field_type')) {
        WP_CLI::error('ACF is not active on this site. Install ACF Pro or Secure Custom Fields first; the target is ACF field groups, not plain post meta.');
    }
    if (! acf_get_field_type('repeater')) {
        WP_CLI::error('This ACF has no repeater field. The pinned schema uses repeaters, so install ACF Pro or Secure Custom Fields.');
    }

    $existing = 0;
    foreach (['post', 'page'] as $post_type) {
        $counts = wp_count_posts($post_type);
        $existing += isset($counts->publish) ? (int) $counts->publish : 0;
    }
    if ($existing > DBVC_CC_TARGET_SITE_MAX_EXISTING_CONTENT) {
        WP_CLI::error(sprintf(
            'Refusing: the site has %d published posts and pages. A disposable target starts empty.',
            $existing
        ));
    }

    $schema_path = '';
    $target = dbvc_cc_target_site_translation($options, $schema_path);
    $path = dbvc_cc_target_site_mu_plugin_path();
    if (is_file($path) && ! dbvc_cc_target_site_is_generated($path)) {
        WP_CLI::error(sprintf('Refusing: %s exists and was not generated by this script.', $path));
    }

    $source_label = sprintf(
        '%s (sha256 %s)',
        str_replace(wp_normalize_path(dirname(__DIR__)) . '/', '', wp_normalize_path($schema_path)),
        hash_file('sha256', $schema_path)
    );
    if (! wp_mkdir_p(WPMU_PLUGIN_DIR) || file_put_contents($path, $target->render_mu_plugin($source_label)) === false) {
        WP_CLI::error('Could not write ' . $path);
    }

    WP_CLI::success(sprintf(
        'Wrote %s: %d post types, %d meta keys, %d ACF field groups from %s.',
        $path,
        count($target->post_types()),
        count($target->post_meta()),
        count($target->field_groups()),
        $source_label
    ));
}

/**
 * @param array<string, string> $options
 * @return void
 */
function dbvc_cc_target_site_verify(array $options)
{
    $path = dbvc_cc_target_site_mu_plugin_path();
    if (! dbvc_cc_target_site_is_generated($path)) {
        WP_CLI::error('The target is not provisioned on this site. Run provision first.');
    }
    if (! class_exists('DBVC_CC_V2_Target_Field_Catalog_Service') || ! class_exists('DBVC_CC_V2_Interpretation_Bridge_Service')) {
        WP_CLI::error('The DBVC content-migration add-on is not loaded on this site.');
    }
    $out = isset($options['out']) ? (string) $options['out'] : '';
    if ($out === '') {
        WP_CLI::error('verify needs out=<path> for the projection.');
    }

    $schema_path = '';
    $target = dbvc_cc_target_site_translation($options, $schema_path);
    $domain = isset($options['domain']) && $options['domain'] !== '' ? $options['domain'] : 'corpus-target-projection.test';
    $projection = DBVC_CC_Corpus_Target_Projection::project($domain, $target);
    if (is_wp_error($projection)) {
        WP_CLI::error($projection->get_error_message());
    }

    $payload = [
        'site_url' => untrailingslashit((string) get_option('siteurl')),
        'schema_sha256' => hash_file('sha256', $schema_path),
        'acf' => defined('ACF_VERSION') ? ACF_VERSION : '',
        'projection' => $projection,
    ];
    if (file_put_contents($out, wp_json_encode($payload, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES)) === false) {
        WP_CLI::error('Could not write ' . $out);
    }

    WP_CLI::success(sprintf('Projected %d objects to %s.', count($projection), $out));
}

/**
 * @return void
 */
function dbvc_cc_target_site_teardown()
{
    $path = dbvc_cc_target_site_mu_plugin_path();
    if (! is_file($path)) {
        WP_CLI::success('Nothing to remove.');
        return;
    }
    if (! dbvc_cc_target_site_is_generated($path)) {
        WP_CLI::error(sprintf('Refusing: %s was not generated by this script.', $path));
    }
    if (! unlink($path)) {
        WP_CLI::error('Could not remove ' . $path);
    }

    WP_CLI::success('Removed ' . $path . '. Content created against the target is left in place.');
}

list($dbvc_cc_command, $dbvc_cc_options) = dbvc_cc_target_site_parse_args(isset($args) && is_array($args) ? $args : []);
dbvc_cc_target_site_guard($dbvc_cc_options);

switch ($dbvc_cc_command) {
    case 'provision':
        dbvc_cc_target_site_provision($dbvc_cc_options);
        break;
    case 'verify':
        dbvc_cc_target_site_verify($dbvc_cc_options);
        break;
    case 'teardown':
        dbvc_cc_target_site_teardown();
        break;
    default:
        WP_CLI::error('Usage: eval-file ' . basename(__FILE__) . ' <provision|verify|teardown> expect-site-url=<url> [slot=<dir>] [out=<path>] [domain=<key>]');
}
